package com.autoops.workflow.entity;import jakarta.persistence.*;@Entity @Table(name="file_transfer_steps")public class FileTransferStep extends WorkflowStep{@Column(name="stored_file_id",nullable=false)private Long storedFileId;@Column(name="destination_path",nullable=false)private String destinationPath;@Column(nullable=false)private boolean overwrite;@Column(name="timeout_seconds",nullable=false)private Integer timeoutSeconds=120;public Long storedFileId(){return storedFileId;}public String destinationPath(){return destinationPath;}}
